import { jest } from '@jest/globals';

describe('Jest Mock Test', () => {
  it('should test jest.fn behavior', () => {
    const mockFn1 = jest.fn();
    const mockFn2 = jest.fn().mockImplementation(() => 'hello');
    
    console.log('mockFn1():', mockFn1());
    console.log('mockFn2():', mockFn2());
    
    expect(mockFn1()).toBeUndefined();
    expect(mockFn2()).toBe('hello');
  });
});